#!/usr/bin/env node
'use strict';

/**
 * Stage 4 of the vocab import pipeline: canonical (translated) data ->
 * the Flutter app's runtime bundle files (`assets/vocab/vocab_{level}.json`,
 * `DATA_MODEL.md` §11.2).
 *
 * Deliberately reads from `output/canonical_vocab_translated.json` (the
 * *local* pipeline artifact), not from Firestore — bundle generation
 * doesn't need Firestore to already be seeded; the translations cache +
 * canonical merge are the actual source of truth for what the bundle
 * contains, and `bin/seed_firestore.js` writes the exact same data, so
 * the two never diverge regardless of which one is run first.
 *
 * Usage: node bin/generate_bundles.js
 */

const fs = require('fs');
const path = require('path');

const { buildBundles } = require('../lib/bundleGen');

const ROOT = path.join(__dirname, '..');
const REPO_ROOT = path.join(ROOT, '..', '..');
const OUTPUT_DIR = path.join(ROOT, 'output');
const TRANSLATED_PATH = path.join(OUTPUT_DIR, 'canonical_vocab_translated.json');
const CANONICAL_PATH = path.join(OUTPUT_DIR, 'canonical_vocab.json');
const ASSETS_DIR = path.join(REPO_ROOT, 'assets', 'vocab');
const TIMESTAMP_CONSTANT_PATH = path.join(
  REPO_ROOT,
  'lib',
  'utils',
  'vocab_bundle_constants.dart'
);

function loadCanonicalData() {
  if (fs.existsSync(TRANSLATED_PATH)) return JSON.parse(fs.readFileSync(TRANSLATED_PATH, 'utf8'));
  if (fs.existsSync(CANONICAL_PATH)) {
    console.warn(
      `⚠ ${path.relative(ROOT, TRANSLATED_PATH)} not found — using untranslated ` +
        `${path.relative(ROOT, CANONICAL_PATH)} (every meaning will have translation: null).`
    );
    return JSON.parse(fs.readFileSync(CANONICAL_PATH, 'utf8'));
  }
  throw new Error('Missing canonical data. Run "node bin/merge.js" first.');
}

function updateTimestampConstant(generatedAt) {
  const millis = generatedAt.getTime();
  const contents =
    `// GENERATED by tools/vocab_import/bin/generate_bundles.js — do not hand-edit.\n` +
    `// Regenerate via: node tools/vocab_import/bin/generate_bundles.js\n` +
    `\n` +
    `/// Timestamp the current \`assets/vocab/*.json\` bundle files were generated\n` +
    `/// at (\`DATA_MODEL.md\` §11.3) — the delta query in\n` +
    `/// \`VocabBundleService.fetchDelta\` uses this to find only vocabulary\n` +
    `/// documents changed *after* the bundle was built.\n` +
    `final DateTime kBundleGeneratedAt = DateTime.fromMillisecondsSinceEpoch(${millis});\n`;
  fs.writeFileSync(TIMESTAMP_CONSTANT_PATH, contents);
}

function main() {
  const documents = loadCanonicalData();
  const { levels, emptyLevels } = buildBundles(documents);

  fs.mkdirSync(ASSETS_DIR, { recursive: true });

  const gitkeepPath = path.join(ASSETS_DIR, '.gitkeep');
  let removedGitkeep = false;

  const written = [];
  for (const [level, entries] of Object.entries(levels)) {
    if (entries.length === 0) continue;
    const filePath = path.join(ASSETS_DIR, `vocab_${level.toLowerCase()}.json`);
    fs.writeFileSync(filePath, JSON.stringify(entries, null, 2));
    written.push({ level, count: entries.length, filePath });
  }

  if (written.length > 0 && fs.existsSync(gitkeepPath)) {
    fs.unlinkSync(gitkeepPath);
    removedGitkeep = true;
  }

  const now = new Date();
  updateTimestampConstant(now);

  console.log('=== Vocab import — Stage 4 (bundle generation) ===');
  for (const w of written) {
    console.log(`  ${path.relative(REPO_ROOT, w.filePath)}: ${w.count} words`);
  }
  if (emptyLevels.length > 0) {
    console.log(`  (no data yet, file not written: ${emptyLevels.join(', ')})`);
  }
  if (removedGitkeep) {
    console.log(`  Removed ${path.relative(REPO_ROOT, gitkeepPath)} (real bundle files now exist).`);
  }
  console.log(
    `  Updated ${path.relative(REPO_ROOT, TIMESTAMP_CONSTANT_PATH)} -> ${now.toISOString()}`
  );

  const untranslatedCount = Object.values(levels)
    .flat()
    .reduce((sum, e) => sum + e.meanings.filter((m) => m.translation === null).length, 0);
  if (untranslatedCount > 0) {
    console.log(
      `\n⚠ ${untranslatedCount} meanings in the generated bundles still have translation: null ` +
        '(run "node bin/translate.js" and regenerate if you want these filled in first).'
    );
  }
}

main();
